import json, os, sys
for line in sys.stdin:
    request = json.loads(line)
    method = request['method']
    with open(os.path.join(os.path.dirname(__file__), 'mcp.log'), 'a', newline='') as log:
        log.write(method + '\n')
    if 'id' not in request:
        continue
    if method == 'initialize':
        result = {'protocolVersion': request['params']['protocolVersion'], 'capabilities': {'tools': {}}, 'serverInfo': {'name': 'binary-fixture', 'version': '1'}}
    elif method == 'tools/list':
        result = {'tools': [{'name': 'echo', 'description': 'Binary MCP echo', 'inputSchema': {'type': 'object', 'properties': {'text': {'type': 'string'}}, 'required': ['text'], 'additionalProperties': False}}]}
    elif method == 'tools/call':
        assert request['params']['name'] == 'echo'
        result = {'content': [{'type': 'text', 'text': 'MCP_BINARY_ECHO:' + request['params']['arguments']['text']}]}
    else:
        raise RuntimeError(method)
    print(json.dumps({'jsonrpc': '2.0', 'id': request['id'], 'result': result}), flush=True)
